({
  async init(msg) {
    this.data = {
      userId: null,
      profile: null,
      posts: [],
      lastFetchedAt: null
    };
    this._checkInvariants();
    return { ok: true };
  },

  async fetchUserFeed(msg) {
    const userId = msg?.payload?.userId;
    this.ensure(typeof userId === "string" || typeof userId === "number", "userId is required and must be a string or number");
    this.ensure(String(userId).trim().length > 0, "userId cannot be empty");

    const httpClient = await this.dep("HttpClient");
    this.ensure(httpClient, "HttpClient dependency must resolve to an AbjectId");

    const profileUrl = `https://api.users.test/profile/${encodeURIComponent(userId)}`;
    const profileResponse = await this.call(httpClient, "get", { url: profileUrl });
    const profile = profileResponse?.data !== undefined ? profileResponse.data : profileResponse;
    this.ensure(profile && typeof profile === "object", "Expected valid profile object from HttpClient");

    let posts = [];
    if (profile.status === "active") {
      const postsUrl = `https://api.users.test/posts?userId=${encodeURIComponent(userId)}`;
      const postsResponse = await this.call(httpClient, "get", { url: postsUrl });
      const rawPosts = postsResponse?.data !== undefined ? postsResponse.data : postsResponse;
      posts = Array.isArray(rawPosts) ? rawPosts : (rawPosts?.posts && Array.isArray(rawPosts.posts) ? rawPosts.posts : []);
    }

    this._applyFeedData(userId, profile, posts);

    const result = {
      userId: this.data.userId,
      profile: this.data.profile,
      posts: this.data.posts,
      lastFetchedAt: this.data.lastFetchedAt
    };

    this.ensure(result.profile !== null && Array.isArray(result.posts), "Postcondition failed: result must contain profile and posts array");
    return result;
  },

  async getFeed(msg) {
    this.ensure(this.data && typeof this.data === "object", "Feed model data must be initialized");
    return { ...this.data };
  },

  _applyFeedData(userId, profile, posts) {
    if (!this.data) {
      this.data = {};
    }
    this.data.userId = userId;
    this.data.profile = profile;
    this.data.posts = posts;
    this.data.lastFetchedAt = Date.now();

    this.changed("feed", this.data);
    this._checkInvariants();
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === "object", "this.data must be an object");
    this.invariant(Array.isArray(this.data.posts), "this.data.posts must be an array");
    this.invariant(
      this.data.profile === null || typeof this.data.profile === "object",
      "this.data.profile must be null or an object"
    );
  }
})
